declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; require_once __DIR__.'/../shared/auth.php'; methodOnly('POST'); requireAdmin(); safeApi(function():void{$db=apiDatabase();$i=jsonRequest();$s=$db->prepare('INSERT INTO blogs(title,slug,excerpt,content,featured_image,status,published_at) VALUES(:title,:slug,:excerpt,:content,:image,:status,:published)');$s->execute([':title'=>inputString($i,'title',true),':slug'=>inputString($i,'slug',true),':excerpt'=>inputString($i,'excerpt'),':content'=>inputString($i,'content',true),':image'=>inputString($i,'featured_image'),':status'=>$i['status']??'DRAFT',':published'=>$i['published_at']??null]);jsonResponse(true,'Blog created successfully.',['id'=>(int)$db->lastInsertId()],[],201);});
